(function () {
  const template = document.createElement('template');

  template.innerHTML = `<slot></slot><style></style>`;

  class Hidden extends HTMLElement {
    #shadow = this.attachShadow({ mode: 'open' });
    #matched = null;

    /**
     *
     */
    get direction() {
      return this.getAttribute('direction');
    }
    /**
     *
     */
    get breakPoint() {
      return this.getAttribute('breakPoint');
    }

    /**
     *
     */
    static get observedAttributes() {
      return ['direction', 'breakPoint'];
    }

    /**
     *
     */
    constructor() {
      super();
    }

    /**
     *
     */
    connectedCallback() {
      const media = window.matchMedia(
        BreakPointRelativeToDirection[this.direction](this.breakPoint)
      );

      if (media.matches !== this.#matched) {
        this.#matched = media.matches;

        this.render();
      }

      media.onchange = (e) => {
        this.#matched = e.matches;

        this.render();
      };
    }

    render() {
      if (this.#matched) {
        this.#shadow.appendChild(template.content.cloneNode(true));
      } else {
        this.#shadow.innerHTML = '';
      }
    }
  }

  const BreakPointSize = {
    xs: 444,
    sm: 600,
    md: 900,
    lg: 1200,
    xl: 1536
  };

  const BreakPointRelativeToDirection = {
    up: (breakPoint) => `(min-width:${BreakPointSize[breakPoint] + 1}px)`,
    down: (breakPoint) => `(max-width:${BreakPointSize[breakPoint]}px)`
  };

  customElements.define('punica-hidden', Hidden);
})();
(function () {
  const template = document.createElement('template');

  template.innerHTML = `<style></style>`;

  class TabPanel extends HTMLElement {
    #shadow = this.attachShadow({ mode: 'open' });
    #slot = null;

    /**
     *
     */
    get value() {
      return this.getAttribute('value');
    }

    /**
     *
     */
    get selectedvalue() {
      return this.getAttribute('selectedvalue');
    }

    /**
     *
     */
    set selectedvalue(val) {
      this.setAttribute('selectedvalue', val);
    }

    /**
     *
     */
    static get observedAttributes() {
      return ['value', 'selectedvalue'];
    }

    /**
     *
     */
    constructor() {
      super();

      this.#shadow.appendChild(template.content.cloneNode(true));
    }

    /**
     *
     * @param {*} name
     * @param {*} oldValue
     * @param {*} newValue
     */
    attributeChangedCallback(name, oldValue, newValue) {
      switch (name) {
        case 'selectedvalue':
          if (newValue == this.value) {
            if (this.#slot == null) {
              this.#slot = document.createElement('slot');

              this.#shadow.appendChild(this.#slot);
              this.style.display = 'block';
            }
          } else if (this.#slot) {
            this.#shadow.removeChild(this.#slot);
            this.#slot = null;
            this.style.display = 'none';
          }
          break;
      }
    }

    /**
     *
     */
    connectedCallback() {
      if (this.selectedvalue == this.value) {
        this.style.display = 'block!important';
      } else {
        this.style.display = 'none!important';
      }
    }
  }

  customElements.define('punica-tab-panel', TabPanel);
})();
(function () {
  const template = document.createElement('template');

  template.innerHTML = `
    <punica-typography color="white">
      <slot></slot>
    </punica-typography>
    <style>:host {   overflow: hidden;   width: 30px;   height: 30px;   position: relative;   display: inline-flex;   -webkit-box-align: center;   align-items: center;   -webkit-box-pack: center;   justify-content: center; }  :host([variant='rounded']) {   border-radius: var(--spacing-4); }  :host([variant='circular']) {   border-radius: 50%; }  ::slotted(img) {   width: 100%;   height: 100%;   text-align: center;   object-fit: cover;   color: transparent;   text-indent: 10000px;   transition: background-color 200ms cubic-bezier(0.4, 0, 0.2, 1) 0ms; } </style>
  `;

  const defaultColorMapping = {
    primary: 'var(--primary-main)',
    secondary: 'var(--secondary-main)',
    error: 'var(--error-main)',
    warning: 'var(--warning-main)',
    info: 'var(--info-main)',
    success: 'var(--success-main)'
  };

  class Avatar extends HTMLElement {
    #shadow = this.attachShadow({ mode: 'open' });

    /**
     *
     */
    get variant() {
      return this.getAttribute('variant');
    }

    /**
     *
     */
    get color() {
      return this.getAttribute('color');
    }

    /**
     *
     */
    static get observedAttributes() {
      return ['variant', 'color'];
    }

    /**
     *
     */
    constructor() {
      super();

      this.#shadow.appendChild(template.content.cloneNode(true));
    }

    /**
     *
     * @param {*} name
     * @param {*} oldValue
     * @param {*} newValue
     */
    attributeChangedCallback(name, oldValue, newValue) {
      switch (name) {
        case 'color':
          if (newValue) {
            const isDefinedColor = defaultColorMapping[newValue];

            if (isDefinedColor) {
              this.style.backgroundColor = isDefinedColor;
            } else {
              this.style.backgroundColor = newValue;
            }
          }
          break;
      }
    }
  }

  customElements.define('punica-avatar', Avatar);
})();
