(function () {
  const template = document.createElement('template');

  template.innerHTML = `<slot></slot><style>:host {   --paper-border-radius: var(--root-border-radius);   --paper-padding: var(--root-padding); }  :host {   display: block;   background-color: var(--background-paper);   padding: var(--paper-padding); }  :host([rounded='true']) {   border-radius: var(--paper-border-radius); } </style>`;

  class Paper extends HTMLElement {
    #shadow = this.attachShadow({ mode: 'open' });

    /**
     *
     */
    get rounded() {
      return this.getAttribute('rounded');
    }

    /**
     *
     */
    get class() {
      return this.getAttribute('class');
    }

    /**
     *
     */
    static get observedAttributes() {
      return ['rounded', 'class'];
    }

    /**
     *
     */
    constructor() {
      super();
    }

    /**
     *
     */
    connectedCallback() {
      this.#shadow.appendChild(template.content.cloneNode(true));
    }

    /**
     *
     * @param {*} name
     * @param {*} oldValue
     * @param {*} newValue
     */
    attributeChangedCallback(name, oldValue, newValue) {
      switch (name) {
        case 'class':
          if (oldValue != newValue) {
            this.className = newValue;
          }
          break;
      }
    }
  }

  customElements.define('punica-paper', Paper);
})();

